"""Offline printable HTML. All user text is escaped before rendering."""
from html import escape

COLUMNS=['Details','Unit','Opening','Receivings','Total stock','Closing','Drawings','Broken','Sold','Unit price','Total amount']


def table(headers,rows):
    def cell(value):return escape(str(value))
    return '<table><thead><tr>'+''.join('<th>'+cell(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+cell(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'


def printable(ledger,period):
    rows,totals=ledger.report(period)
    selected_shop=SHOPS.get(getattr(ledger,'shop_id',None),('Shop records',''))[0]
    dates=ledger.db.execute('SELECT start,end FROM periods WHERE id=?',(period,)).fetchone()
    if not dates:raise ValueError('Reporting period not found.')
    warnings=ledger.checks(period)
    valuations=[]
    for item in ledger.db.execute('SELECT s.product,p.name FROM stock s JOIN products p ON p.id=s.product WHERE period=? ORDER BY p.name',(period,)):
        valuation=ledger.inventory_valuation(period,item['product'])
        valuations.append([item['name'],valuation['method'],f"{valuation['cogs']/100:.2f}",f"{valuation['closing_value']/100:.2f}"])
    balances=[[r['name'],f"{r['credit']/100:.2f}",f"{r['paid']/100:.2f}",f"{(r['credit']-r['paid'])/100:.2f}"] for r in ledger.customer_balances()]
    return '''<!doctype html><html><head><meta charset="utf-8"><title>Mutowei Investments — stock and income report</title>
<style>body{font:14px Arial,sans-serif;color:#172b35;max-width:1300px;margin:30px auto;padding:0 18px}h1{color:#17685b}h2{margin-top:30px}table{border-collapse:collapse;width:100%;margin:15px 0}th,td{border:1px solid #cbd5da;padding:8px;text-align:right}th{background:#eaf4f0}td:first-child,th:first-child{text-align:left}.note{padding:12px;background:#fff4da}.sign{margin-top:40px;line-height:3}button{padding:10px 20px;cursor:pointer}@media print{button{display:none}body{font-size:10px;margin:0;max-width:none}th,td{padding:5px}thead{display:table-header-group}tr{break-inside:avoid}.sign{break-inside:avoid}@page{size:A4 landscape;margin:12mm}}</style></head><body>
<button onclick="window.print()">Print / Save as PDF</button><h1>MUTOWEI INVESTMENTS</h1><p><strong>WhatKind?</strong></p>''' + f'<h2>{escape(selected_shop)}</h2><p>Stock and income report | {escape(dates[0])} to {escape(dates[1])} | USD</p>' + '<p class="note">Provisional report based on complete stock counts and supplied costs. Stock-implied sales may include unexplained losses; investigate the reconciliation difference. Customer balances below cover all recorded dates, not only this period.</p>'+ ('<h2>Checks requiring attention</h2><ul>'+''.join('<li>'+escape(w)+'</li>' for w in warnings)+'</ul>' if warnings else '')+'<h2>Stock sheet</h2>'+table(COLUMNS,rows)+'<h2>Reconciliation and income statement</h2>'+table(['Details','Amount USD'],totals.items())+'<p>Cost of goods sold uses the selected FIFO or weighted-average method, including allocated delivery costs. FIFO uses period totals: sales first, drawings second, breakages last; category costs are provisional when movement dates are unknown. Total-sales entries retain the entered amount and show an average selling price. Drawings are excluded from sales and expenses. Unexplained cash differences are not automatically deducted from profit.</p><h2>Inventory valuation methods</h2>'+table(['Product','Method','Cost of sales USD','Closing value USD'],valuations)+'<h2>Customer balances — all recorded dates</h2>'+table(['Customer','Credit sales USD','Repaid USD','Balance USD'],balances)+'<div class="sign">Prepared by: __________________________ &nbsp; Signature: __________________________<br>Checked by: __________________________ &nbsp; Signature: __________________________<br>Date: __________________________</div></body></html>'


BRAND_PAYLOAD = ''

APP_ID = 'MutoweiInvestments.Desktop.App'


def materialize_brand():
    import base64,json,zlib
    payload=json.loads(zlib.decompress(base64.b64decode(BRAND_PAYLOAD)))
    folder=DATA/'assets';folder.mkdir(exist_ok=True)
    for ext in ('ico','png'):
        path=folder/('mutowei-v1.'+ext);data=base64.b64decode(payload[ext])
        if not path.exists() or path.read_bytes()!=data:path.write_bytes(data)
    return folder


def set_process_identity():
    if os.name=='nt':
        try:
            import ctypes
            function=ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID
            function.argtypes=[ctypes.c_wchar_p];function.restype=ctypes.c_long
            function(APP_ID)
        except (AttributeError,OSError):pass


def set_shortcut_identity(path):
    """Match the shortcut AppUserModelID to the running app (Windows COM)."""
    if os.name!='nt':return
    import ctypes as C
    from ctypes import wintypes as W
    import uuid
    class GUID(C.Structure):
        _fields_=[('data',C.c_ubyte*16)]
        def __init__(self,text):super().__init__((C.c_ubyte*16).from_buffer_copy(uuid.UUID(text).bytes_le))
    class PROPERTYKEY(C.Structure):_fields_=[('fmtid',GUID),('pid',W.DWORD)]
    class VALUE(C.Union):_fields_=[('text',C.c_wchar_p),('padding',C.c_ubyte*16)]
    class PROPVARIANT(C.Structure):_fields_=[('vt',W.WORD),('a',W.WORD),('b',W.WORD),('c',W.WORD),('value',VALUE)]
    ole=C.OleDLL('ole32');ole.CoInitialize(None)
    link=C.c_void_p();persist=C.c_void_p();store=C.c_void_p()
    def call(ptr,index,types,*args):
        table=C.cast(ptr,C.POINTER(C.POINTER(C.c_void_p))).contents
        return C.WINFUNCTYPE(C.c_long,C.c_void_p,*types)(table[index])(ptr,*args)
    def checked(result):
        if result<0:raise OSError('Windows shortcut identity could not be updated.')
    try:
        cls=GUID('00021401-0000-0000-C000-000000000046');iid=GUID('000214F9-0000-0000-C000-000000000046')
        ole.CoCreateInstance.argtypes=[C.POINTER(GUID),C.c_void_p,W.DWORD,C.POINTER(GUID),C.POINTER(C.c_void_p)]
        checked(ole.CoCreateInstance(C.byref(cls),None,1,C.byref(iid),C.byref(link)))
        iidfile=GUID('0000010B-0000-0000-C000-000000000046')
        checked(call(link,0,[C.POINTER(GUID),C.POINTER(C.c_void_p)],C.byref(iidfile),C.byref(persist)))
        checked(call(persist,5,[C.c_wchar_p,W.DWORD],str(path),2))
        iidstore=GUID('886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99')
        checked(call(link,0,[C.POINTER(GUID),C.POINTER(C.c_void_p)],C.byref(iidstore),C.byref(store)))
        key=PROPERTYKEY(GUID('9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3'),5)
        value=PROPVARIANT();value.vt=31;value.value.text=APP_ID
        checked(call(store,6,[C.POINTER(PROPERTYKEY),C.POINTER(PROPVARIANT)],C.byref(key),C.byref(value)))
        checked(call(store,7,[]))
        checked(call(persist,6,[C.c_wchar_p,W.BOOL],str(path),True))
    finally:
        for pointer in (store,persist,link):
            if pointer:call(pointer,2,[])
        ole.CoUninitialize()


def scroll_target(widget,axis,motion,parents):
    """Route to the nearest viewport that can move, then its enclosing page."""
    seen=set()
    while widget is not None:
        target=parents.get(widget,widget)
        if target not in seen:
            seen.add(target)
            view=getattr(target,axis+'view',None)
            if view:
                try:
                    first,last=map(float,view())
                    if (motion<0 and first>0.000001) or (motion>0 and last<0.999999):return target
                except (tk.TclError,TypeError,ValueError):pass
        widget=getattr(widget,'master',None)
    return None


def blend_color(start,end,progress):
    progress=max(0.0,min(1.0,progress))
    values=[round(int(start[i:i+2],16)+(int(end[i:i+2],16)-int(start[i:i+2],16))*progress) for i in (1,3,5)]
    return '#'+''.join(f'{value:02x}' for value in values)


SHOPS = {
    'mutowei-bottle-store': ('Mutowei Bottle Store','Bottle store'),
    'bizzy-tuckshop': ('Bizzy Tuckshop','Grocery & beer'),
    'chikofa-tuckshop': ('Chikofa Tuckshop','Grocery & beer'),
}


def shop_database(root,shop):
    if shop not in SHOPS:raise ValueError('Choose one of the three shops.')
    folder=Path(root)/'shops'/shop;folder.mkdir(parents=True,exist_ok=True)
    return folder/'shop.sqlite3'


def database_has_records(path):
    import sqlite3
    path=Path(path)
    if not path.exists():return False
    from contextlib import closing
    with closing(sqlite3.connect(path.resolve().as_uri()+'?mode=ro',uri=True)) as db:
        tables={r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        return any(db.execute(f'SELECT 1 FROM {name} LIMIT 1').fetchone() for name in ['products','periods','stock','receipts','cash','orders','debts'] if name in tables)


def assign_shop(ledger,shop):
    if shop not in SHOPS:raise ValueError('Unknown shop.')
    ledger.db.execute('CREATE TABLE IF NOT EXISTS shop_identity(id INTEGER PRIMARY KEY CHECK(id=1),shop TEXT NOT NULL)')
    current=ledger.db.execute('SELECT shop FROM shop_identity WHERE id=1').fetchone()
    if current and current[0]!=shop:raise ValueError('This database belongs to another shop. Restore it in its matching section.')
    with ledger.db:ledger.db.execute('INSERT OR IGNORE INTO shop_identity(id,shop) VALUES (1,?)',(shop,))


def migrate_legacy(root,shop):
    """Copy only after an explicit destination choice. Preserve the original."""
    import sqlite3,tempfile,json
    from contextlib import closing
    from datetime import datetime
    root=Path(root);source=root/'shop.sqlite3';destination=shop_database(root,shop)
    if (root/'legacy-assigned.json').exists():raise ValueError('Earlier records have already been assigned.')
    if not database_has_records(source):raise ValueError('No earlier records were found.')
    if database_has_records(destination):raise ValueError('The selected shop already has records. Assignment will not overwrite them.')
    backup=root/('before-shop-assignment-'+datetime.now().strftime('%Y%m%d-%H%M%S')+'.sqlite3')
    with closing(sqlite3.connect(source.resolve().as_uri()+'?mode=ro',uri=True)) as original,closing(sqlite3.connect(backup)) as copy:original.backup(copy)
    fd,name=tempfile.mkstemp(suffix='.sqlite3',dir=destination.parent);os.close(fd);temporary=Path(name)
    try:
        with closing(sqlite3.connect(backup)) as original,closing(sqlite3.connect(temporary)) as copy:original.backup(copy)
        ledger=Ledger(temporary)
        try:assign_shop(ledger,shop)
        finally:ledger.db.close()
        os.replace(temporary,destination)
        (root/'legacy-assigned.json').write_text(json.dumps({'shop':shop,'backup':backup.name}),encoding='utf-8')
    finally:temporary.unlink(missing_ok=True)
    return destination


