    def switch_shop(self,shop,force=False):
        if shop not in SHOPS:return
        if shop==self.shop_id and not force:return
        draft=self.scan_draft.get('1.0','end').strip() if hasattr(self,'scan_draft') else ''
        if draft and not messagebox.askyesno('Switch shop','Discard the unsaved scan draft and switch shops? Saved records will not change.'):
            return
        path=shop_database(DATA,shop)
        replacement=Ledger(path)
        try:assign_shop(replacement,shop)
        except Exception:
            replacement.db.close();raise
        self.ledger.db.close();self.ledger=replacement;self.ledger.shop_id=shop
        self.shop_id=shop;self.db_path=path;self.shop_data=path.parent
        import json
        try:(DATA/'business-settings.json').write_text(json.dumps({'shop':shop}),encoding='utf-8')
        except OSError as exc:messagebox.showerror('Shop preference',str(exc))
        self.title('Mutowei Investments — '+SHOPS[shop][0])
        self.shop_subtitle.configure(text=SHOPS[shop][0]+'  •  '+SHOPS[shop][1]+'  •  WhatKind?')
        self.paint_shops()
        # A session may be reused, but its client/namespace is always replaced.
        if self.cloud:
            from ledger import Cloud
            old=self.cloud;self.cloud=Cloud(old.url,old.key,shop=shop);self.cloud.token=old.token;self.cloud.owner=old.owner
            self.cloud_status.configure(text='ONLINE SESSION — '+SHOPS[shop][0])
        self.scan_text.delete('1.0','end');self.scan_draft.delete('1.0','end');self.scan_source='Pasted text';self.scan_unparsed=[]
        self.scan_notice.configure(text='Selected shop: '+SHOPS[shop][0]+'. Choose a reporting period before importing.')
        self.history_text.configure(state='normal');self.history_text.delete('1.0','end');self.history_text.configure(state='disabled')
        grab=self.grab_current()
        for child in self.winfo_children():
            if isinstance(child,tk.Toplevel) and child is not grab:child.destroy()
        self.reload_periods();self.navigate(0)

    def offer_legacy(self,force=False):
        if (DATA/'legacy-assigned.json').exists() or not database_has_records(DATA/'shop.sqlite3'):
            if force:messagebox.showinfo('Earlier records','No unassigned earlier records were found.')
            return
        options={name:key for key,(name,_) in SHOPS.items()}
        def save(v):
            if v['Destination shop'] not in options:raise ValueError('Select the shop these earlier records belong to.')
            key=options[v['Destination shop']]
            if database_has_records(shop_database(DATA,key)):raise ValueError('That shop already has records. Assignment will not overwrite them.')
            active=key==self.shop_id
            if active:self.ledger.db.close()
            try:migrate_legacy(DATA,key)
            finally:
                if active:
                    self.ledger=Ledger(self.db_path);assign_shop(self.ledger,self.shop_id);self.ledger.shop_id=self.shop_id
            self.switch_shop(key,force=True)
            messagebox.showinfo('Records assigned','Earlier records were copied to '+SHOPS[key][0]+'. The original and a dated backup were preserved.')
        self.form('Choose where your earlier records belong',[('Destination shop','Select a shop...',list(options))],save,preview=lambda v:'Earlier records will be copied only to the shop you choose. Close this dialog to leave them unassigned and decide later. Nothing will be copied to all three shops.')

    def load_motion(self):
        import json
        try:return bool(json.loads((DATA/'motion-settings.json').read_text()).get('reduce_motion',False))
        except (OSError,ValueError,AttributeError):return False

    def animate(self,key,duration,step):
        import time
        previous=self._animations.pop(key,None)
        if previous:
            try:self.after_cancel(previous['after'])
            except tk.TclError:pass
        if self.reduce_motion.get():step(1.0);return
        started=time.perf_counter()
        job={'after':None,'finish':lambda:step(1.0)}
        self._animations[key]=job
        def tick():
            if self._animations.get(key) is not job:return
            progress=min(1.0,(time.perf_counter()-started)*1000/max(1,duration))
            eased=1-(1-progress)**3
            try:step(eased)
            except tk.TclError:self._animations.pop(key,None);return
            if progress<1:job['after']=self.after(25,tick)
            else:self._animations.pop(key,None)
        tick()

    def toggle_motion(self):
        import json
        try:(DATA/'motion-settings.json').write_text(json.dumps({'reduce_motion':self.reduce_motion.get()}),encoding='utf-8')
        except OSError as exc:messagebox.showerror('Motion preference',str(exc))
        if self.reduce_motion.get():
            jobs=list(self._animations.values());self._animations.clear()
            for job in jobs:
                try:
                    self.after_cancel(job['after']);job['finish']()
                except tk.TclError:pass

